insert into public.pets (slug, published, sort_order, tag_ids, curator_id, donation_id, doc)
values
  ('kotik', true, 1, ARRAY['cat', 'young', 'calm', 'fiv', 'tbilisi', 'needs-home']::text[], (select id from public.curators where slug = 'mykhailo'), (select id from public.donation_links where slug = 'kotik-bog'), '{"name":{"ru":"Котик","en":"Kotik","ka":"კოტიკი"},"subtitle":{"ru":"Дворовой кот из Тбилиси","en":"Street cat from Tbilisi","ka":"ქუჩის კატა თბილისიდან"},"location":{"ru":"Тбилиси","en":"Tbilisi","ka":"თბილისი"},"status":{"ru":"Нужна помощь","en":"Help needed","ka":"საჭიროებს დახმარებას"},"statusType":"warning","tags":["cat","young","calm","fiv","tbilisi","needs-home"],"mainPhoto":{"src":"media/kotik-2026-03-12.webp","thumb":"media/thumbs/kotik-2026-03-12.webp","alt":{"ru":"Котик спит, свернувшись клубком, на пледе","en":"Kotik curled up asleep on a blanket","ka":"კოტიკს გორგალივით დახვეულს სძინავს საბანზე"}},"shortDescription":{"ru":"Молодой дворовой кот из итальянского дворика. У него выявили ВИК и воспаление; нужны чистка зубов под седацией, УЗИ и дом, где он не будет контактировать с другими кошками.","en":"A young street cat from an Italian courtyard. Diagnosed with FIV and inflammation; he needs dental work under sedation, an ultrasound, and a home away from other cats.","ka":"ახალგაზრდა ქუჩის კატა იტალიური ეზოდან. აღმოაჩნდა FIV და ანთება; სჭირდება კბილების მკურნალობა სედაციის ქვეშ, ექოსკოპია და სახლი სხვა კატებისგან მოშორებით."},"description":{"ru":"Котик — молодой, сдержанный и очень независимый дворовой кот, живущий в обычном итальянском дворике в Тбилиси. Так сложилось, что я живу в том же итальянском дворике и кормлю местных кошек, и Котик начал приходить ко мне — не сразу, но, видимо, взяв пример со своих пушистых собратьев, он решил, что я не так уж страшен. Зимой он грелся на диване по ночам, весной перестал гостить, но каждый день приходил за едой и общением.\n\nНе так давно я заметил, что с ним что-то не так. Сильный неприятный запах изо рта, вялость — он мог несколько часов просидеть на одном месте, не двигаясь, затем отойти за едой на несколько минут — и опять вернуться на свой пост, на следующие несколько часов. Шерсть стала тусклая, походка неуверенная. Он чесался, не набирал вес, хотя ел с избытком, постоянно много пил.\n\nМы с женой не могли на это спокойно смотреть, и отнесли его к ветеринару. Как выяснилось, не зря: во время осмотра был выявлен ВИК (вирус иммунодефицита кошек), а также его постоянный спутник — воспалительный процесс. ВИК не лечится, но воспаление можно снять. Кроме того, нужны дополнительные исследования, которые могут показать другие заболевания. И кота нужно как-то изолировать от других кошек — так что было бы неплохо найти для него дом: я снимаю квартиру, и котов держать мне нельзя. Да и квартира очень маленькая, а Котик привык к жизни во дворе и дома сидеть отказывается.\n\nМы оплатили первичный осмотр, анализы, обработку от паразитов и базовые лекарства. Однако Котику всё ещё требуется чистка зубов под седацией, УЗИ брюшной полости и дальнейший уход. На это у меня, к сожалению, нет средств, и я прошу помощи у неравнодушных людей.","en":"Kotik is a young, reserved, and very independent street cat living in a typical Italian courtyard in Tbilisi. It so happened that I live in the same courtyard and feed the local cats, so Kotik started coming to me — not right away, but apparently taking a cue from his furry brethren, he decided I wasn’t so scary after all. In the winter he warmed himself on the couch at night; in the spring he stopped visiting, but came every day for food and companionship.\n\nNot long ago I noticed something was wrong with him. A strong, unpleasant odour on his breath, and lethargy — he would sit in one place for several hours without moving, then go off for food for a few minutes, and return to his post for the next several hours. His fur became dull and his gait unsteady. He scratched himself and wasn’t gaining weight, despite eating abundantly and constantly drinking a lot.\n\nMy wife and I couldn’t stand it and took him to the vet. As it turned out, it was worth it: the examination revealed FIV (feline immunodeficiency virus) along with its constant companion — an inflammatory process. FIV is incurable, but the inflammation can be reduced. Additional tests are also needed, which could reveal other conditions. And he needs to be kept away from other cats, so it would be good to find him a home: I rent an apartment and am not allowed to keep cats. The apartment is very small too, and Kotik is used to life in the courtyard and refuses to stay indoors.\n\nWe paid for the initial examination, tests, parasite treatment, and basic medications. However, Kotik still needs a teeth cleaning under sedation, an abdominal ultrasound, and ongoing care. Unfortunately I don’t have the funds for this, and I’m asking for help from caring people.","ka":"კოტიკი ახალგაზრდა, თავშეკავებული და ძალიან დამოუკიდებელი ქუჩის კატაა, რომელიც თბილისურ ტიპურ იტალიურ ეზოში ცხოვრობს. შემთხვევით მეც იმავე იტალიურ ეზოში ვცხოვრობ და ადგილობრივ კატებს ვკვებავ, ამიტომ კოტიკმა ჩემთან მოსვლა დაიწყო — არა მაშინვე, მაგრამ, როგორც ჩანს, თავისი ბეწვიანი ძმებისგან მაგალითს იღებდა და გადაწყვიტა, რომ ბოლოს და ბოლოს, არც ისე საშინელი ვიყავი. ზამთარში ღამით დივანზე თბებოდა; გაზაფხულზე კი აღარ სტუმრობდა, მაგრამ ყოველდღე მოდიოდა საჭმლისა და ურთიერთობისთვის.\n\nარც ისე დიდი ხნის წინ შევნიშნე, რომ რაღაც სჭირდა. სუნთქვაში ძლიერი, უსიამოვნო სუნი ჰქონდა და ლეთარგიული იყო — რამდენიმე საათის განმავლობაში ერთ ადგილას იჯდა უმოძრაოდ, შემდეგ რამდენიმე წუთით საჭმელად მიდიოდა და შემდეგ რამდენიმე საათის განმავლობაში თავის ადგილს უბრუნდებოდა. ბეწვი გაუფერულდა და სიარული არამყარი ჰქონდა. თავს იფხანდა და წონაში არ იმატებდა, მიუხედავად იმისა, რომ უხვად ჭამდა და მუდმივად ბევრს სვამდა.\n\nმე და ჩემმა მეუღლემ ვერ გავუძელით და ვეტერინართან წავიყვანეთ. როგორც აღმოჩნდა, ღირდა: გამოკვლევის დროს აღმოჩნდა კატის იმუნოდეფიციტის ვირუსი (FIV) და მისი მუდმივი თანმხლები — ანთებითი პროცესი. FIV განუკურნებელია, მაგრამ ანთების შემცირება შესაძლებელია. გარდა ამისა, საჭიროა დამატებითი ანალიზები, რომლებმაც შეიძლება სხვა დაავადებები გამოავლინოს. კატა ასევე საჭიროებს იზოლირებას სხვა კატებისგან, ამიტომ კარგი იქნებოდა მისთვის სახლის პოვნა: ბინას ვქირაობ და კატებს ვერ ვამყოფებ. ბინაც ძალიან პატარაა, კოტიკი კი მიჩვეულია ეზოში ცხოვრებას და უარს ამბობს სახლში დარჩენაზე.\n\nჩვენ დავფარეთ საწყისი გამოკვლევის, ანალიზების, პარაზიტების მკურნალობისა და ძირითადი მედიკამენტების ხარჯები. თუმცა, კოტიკს ჯერ კიდევ სჭირდება კბილების გაწმენდა სედაციის ქვეშ, მუცლის ღრუს ულტრაბგერითი გამოკვლევა და მუდმივი მოვლა. სამწუხაროდ, ამისთვის სახსრები არ მაქვს და დახმარებას მზრუნველი ადამიანებისგან ვითხოვ."},"gallery":[{"type":"image","src":"media/kotik-2026-03-12.webp","thumb":"media/thumbs/kotik-2026-03-12.webp","alt":{"ru":"Котик спит, свернувшись клубком, на пледе","en":"Kotik curled up asleep on a blanket","ka":"კოტიკს გორგალივით დახვეულს სძინავს საბანზე"}},{"type":"image","src":"media/kotik-2025-09-08.webp","thumb":"media/thumbs/kotik-2025-09-08.webp","alt":{"ru":"Котик сидит на деревянном полу и смотрит в сторону","en":"Kotik sitting on a wooden floor, looking to one side","ka":"კოტიკი ხის იატაკზე ზის და გვერდით იყურება"}},{"type":"image","src":"media/kotik-2025-11-06.webp","thumb":"media/thumbs/kotik-2025-11-06.webp","alt":{"ru":"Котик спит на кровати рядом с жёлтой подушкой","en":"Kotik asleep on a bed next to a yellow pillow","ka":"კოტიკს საწოლზე, ყვითელი ბალიშის გვერდით სძინავს"}},{"type":"image","src":"media/kotik-2025-11-16.webp","thumb":"media/thumbs/kotik-2025-11-16.webp","alt":{"ru":"Котик спит на диване, спрятав лапы","en":"Kotik asleep on the sofa with his paws tucked in","ka":"კოტიკს დივანზე სძინავს, თათებამოკეცილს"}},{"type":"image","src":"media/kotik-2025-11-30.webp","thumb":"media/thumbs/kotik-2025-11-30.webp","alt":{"ru":"Котик спит на спине, раскинувшись на пледе","en":"Kotik sleeping on his back, stretched out on a blanket","ka":"კოტიკს ზურგზე გაშოტილს სძინავს საბანზე"}},{"type":"image","src":"media/kotik-2026-05-04.webp","thumb":"media/thumbs/kotik-2026-05-04.webp","alt":{"ru":"Котика держат на руках, он мяукает","en":"Kotik being held in someone’s arms, meowing","ka":"კოტიკი ხელში უჭირავთ და კნავის"}},{"type":"image","src":"media/kotik-2026-05-04a.webp","thumb":"media/thumbs/kotik-2026-05-04a.webp","alt":{"ru":"Крупный план мордочки Котика","en":"Close-up of Kotik’s face","ka":"კოტიკის სახის ახლო ხედი"}}],"video":null,"carePlan":[{"state":"done","title":{"ru":"Анализы крови и осмотр","en":"Blood tests & initial exam","ka":"სისხლის ანალიზი და გასინჯვა"},"desc":{"ru":"Оплачено. Выявлен ВИК, воспаление (WBC 23.2).","en":"Paid. Diagnosed with FIV & inflammation (WBC 23.2).","ka":"გადახდილია. გამოვლინდა FIV და ანთება (WBC 23.2)."}},{"state":"done","title":{"ru":"Обработка от паразитов и препараты","en":"Parasite treatment & medications","ka":"პარაზიტებისგან დამუშავება და მედიკამენტები"},"desc":{"ru":"Нексгард комбо, курс Доксициклина и Триттико.","en":"NexGard Combo, a course of Doxycycline, and Trittico.","ka":"NexGard Combo, დოქსიციკლინი და ტრიტიკო."}},{"state":"needed","title":{"ru":"Санация ротовой полости","en":"Dental sanitation","ka":"პირის ღრუს სანიტაცია"},"desc":{"ru":"Чистка зубов и обработка дёсен под седацией в ветеринарной клинике.","en":"Tooth cleaning and gum treatment under sedation at the vet clinic.","ka":"კბილების გაწმენდა და ღრძილების დამუშავება სედაციის ქვეშ ვეტერინარულ კლინიკაში."}},{"state":"needed","title":{"ru":"УЗИ брюшной полости","en":"Abdominal ultrasound","ka":"მუცლის ღრუს ულტრაბგერა (ექოსკოპია)"},"desc":{"ru":"Рекомендовано в клинике «Киви» (д-р Болюх / Михайлова).","en":"Recommended at Kiwi Clinic (Dr. Bolyukh / Mykhailova).","ka":"რეკომენდებულია კლინიკა «კივი»-ში (დრ. ბოლიუხი / მიხაილოვა)."}}],"docs":[{"href":"assets/blood_test.png","label":{"ru":"Анализ крови (27.06)","en":"Blood test (27.06)","ka":"სისხლის ანალიზი (27.06)"},"sub":{"ru":"Клиника ZooFamily","en":"ZooFamily Clinic","ka":"კლინიკა ZooFamily"}},{"href":"assets/vet_recommendation.png","label":{"ru":"Назначения врача","en":"Vet prescriptions","ka":"ექიმის დანიშნულება"},"sub":{"ru":"Рекомендации","en":"Recommendations","ka":"რეკომენდაციები"}}],"sections":[{"icon":"fa-guitar","title":{"ru":"Благотворительные выступления","en":"Charity guitar performances","ka":"საქველმოქმედო გამოსვლები"},"body":{"ru":"В ближайшее время я планирую проводить небольшие акустические выступления (играю на гитаре и пою) на улицах и площадках Тбилиси в поддержку сбора средств для Котика. Следите за обновлениями и новыми фото/видео на этой странице!","en":"I plan to perform short acoustic sets (singing and playing guitar) around the streets and venues of Tbilisi to help raise funds for Kotik. Stay tuned for updates, photos, and clips on this page!","ka":"უახლოეს მომავალში ვგეგმავ მცირე აკუსტიკურ გამოსვლებს (გიტარაზე დაკვრა და სიმღერა) თბილისის ქუჩებსა და მოედნებზე კოტიკის მხარდასაჭერად. ადევნეთ თვალი სიახლეებს და ახალ ფოტო/ვიდეო მასალას ამ გვერდზე!"}}]}'::jsonb)
on conflict (slug) do update set
  published   = excluded.published,
  sort_order  = excluded.sort_order,
  tag_ids     = excluded.tag_ids,
